window.kbPageData["views/entry/k-e03ee051700aaf63"] = {"key":"entry/k-e03ee051700aaf63","state":{"route":"entry/k-e03ee051700aaf63"},"node":{"id":"k-e03ee051700aaf63","mode":"k","title":"可遇不可求与可望不可即","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["可遇不可求与可望不可即的词义辨析","“可遇不可求”与“可望不可即”的词义辨析"],"qs":["江苏 2023 A类 行测#40","江苏 2023 B类 行测#31"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"可遇不可求指有机会遇到或得到，但无法凭意愿强求。可望不可即指可以望见或向往，却难以接近或实现。","review":{"definition":"可遇不可求指有机会遇到或得到，但无法凭意愿强求。可望不可即指可以望见或向往，却难以接近或实现。","explanation":"材料说有些才能杰出者“或许可以”提出创造性思想，并认为创造性成果不宜预先设为目标。第二空用“可遇不可求”，突出成果有可能出现，却难以强求。“可望不可即”侧重目标难以企及，“不可多得”则侧重成果稀少。","references":[],"evidence":"有些才能杰出者或许可以提出富有创造性的思想","disposition":"独立词条","basis":"据原题和解析编释。","title":"可遇不可求与可望不可即","related":[],"examFocus":{"江苏 2023 A类 行测#40":"结合“或许可以”和“不应该是预先设立的目标”，辨析第二空的成语分别侧重成果出现的机会、目标能否企及，还是成果是否罕见。"}},"readings":[{"origin":"k-e03ee051700aaf63","title":"可遇不可求与可望不可即","qs":["江苏 2023 A类 行测#40"],"definition":"可遇不可求指有机会遇到或得到，但无法凭意愿强求。可望不可即指可以望见或向往，却难以接近或实现。","explanation":"材料说有些才能杰出者“或许可以”提出创造性思想，并认为创造性成果不宜预先设为目标。第二空用“可遇不可求”，突出成果有可能出现，却难以强求。“可望不可即”侧重目标难以企及，“不可多得”则侧重成果稀少。","evidence":"有些才能杰出者或许可以提出富有创造性的思想","doubt":"","references":[]},{"origin":"k-f3b40ee578191ceb","title":"可遇不可求与可望不可即","qs":["江苏 2023 B类 行测#31"],"definition":"“可遇不可求”指有机会遇到或获得，却难以靠刻意追求得来。“可望不可即”指可以望见或向往，却难以接近或达到。","explanation":"材料认为，有些才能杰出的人文学者或许会提出原创思想，甚至形成自己的理论体系，但这不应当成为预先设立的目标。第二空要表达的是成果可能出现、难以强求，所以“可遇不可求”比侧重目标难以企及的“可望不可即”更贴切。","evidence":"有些才能杰出者或许可以提出富有创造性的思想","doubt":"","references":[]}]},"questions":{"江苏 2023 A类 行测#40":{"paper":"江苏 2023 A类 行测","n":40,"mod":"言语理解与表达","src":["22304fe4c340e19d7902.pdf",8],"asrc":["be17f9afe070cf13a0fb.pdf",13],"card":"c3f6840173763ae79d206f89","links":[{"id":"k-e03ee051700aaf63","role":"直接考查","why":"第二空要区分偶然可得、无法强求与眼下难以企及两层意思。"}]},"江苏 2023 B类 行测#31":{"paper":"江苏 2023 B类 行测","n":31,"mod":"言语理解与表达","src":["22262c34d18cd68fbee4.pdf",5],"asrc":["b08f2713d73015eac675.pdf",11],"card":"bc0def24be0bffe920001649","links":[{"id":"k-e03ee051700aaf63","role":"直接考查","why":"前者强调无法刻意求得，后者强调可以看到或向往却难以达到，这一区别决定第二空的取舍。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-e03ee051700aaf63":[["江苏 2023 A类 行测#40","江苏 2023 B类 行测#31"]]}};
